import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMutation } from '@tanstack/react-query';
import { useForm, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import {
  Button,
  Form,
  Select,
  InputNumber,
  Input,
  Alert,
  Typography,
  Space,
} from 'antd';
import { PageContainer } from '@/components/PageContainer';
import { apiClient } from '@/api/client';
import type { LoanApplicationResponse } from '@/types/models';

const { Title } = Typography;
const { TextArea } = Input;

const termOptions = [
  { label: '12个月', value: 12 },
  { label: '24个月', value: 24 },
  { label: '36个月', value: 36 },
  { label: '48个月', value: 48 },
  { label: '60个月', value: 60 },
];

const validTerms = termOptions.map((o) => o.value);

const loanSchema = z.object({
  amount: z.number().positive('贷款金额必须大于0'),
  termMonths: z.number().refine((v) => validTerms.includes(v), '请选择贷款期限'),
  purpose: z
    .string()
    .min(1, '请输入贷款用途')
    .max(500, '贷款用途不能超过500字'),
});

type LoanFormData = z.infer<typeof loanSchema>;

export function LoanApply(): JSX.Element {
  const navigate = useNavigate();
  const [submitError, setSubmitError] = useState<string | null>(null);

  const { control, handleSubmit } = useForm<LoanFormData>({
    resolver: zodResolver(loanSchema),
    defaultValues: {
      amount: 0,
      termMonths: 0,
      purpose: '',
    },
  });

const mutation = useMutation<LoanApplicationResponse, Error, LoanFormData>({
    mutationFn: async (data) => {
      return apiClient.post<LoanApplicationResponse>('/loans/applications', {
        amount: data.amount.toFixed(2),
        termMonths: data.termMonths,
        purpose: data.purpose,
      });
    },
    onSuccess: (response) => {
      navigate(`/loans/${response.loanId}`);
    },
    onError: (error) => {
      setSubmitError(error.message);
    },
  });

  const onSubmit = (data: LoanFormData): void => {
    setSubmitError(null);
    mutation.mutate(data);
  };

  return (
    <PageContainer pageId="customer.loans.apply" state="READY" title="申请贷款">
      <div style={{ padding: '24px', maxWidth: 600 }}>
        <Title level={4}>填写贷款申请信息</Title>

        {submitError !== null && (
          <Alert
            type="error"
            message="申请失败"
            description={submitError}
            style={{ marginBottom: 24 }}
            closable
            onClose={() => setSubmitError(null)}
            data-testid="loan-apply-error"
          />
        )}

import { useQuery } from '@tanstack/react-query';
import { Card, Descriptions, Skeleton, Empty } from 'antd';
import { PageContainer } from '@/components/PageContainer';
import type { PageState } from '@/components/PageContainer';
import { apiClient } from '@/api/client';
import type { CustomerProfile } from '@/types/models';

export function Profile(): JSX.Element {
  const { data, isLoading, isError } = useQuery<CustomerProfile>({
    queryKey: ['profile'],
    queryFn: () => apiClient.get<CustomerProfile>('/profile'),
  });

  const pageState: PageState = isLoading
    ? 'LOADING'
    : isError
      ? 'ERROR'
      : 'READY';

  return (
    <PageContainer
      pageId="customer.profile"
      state={pageState}
      title="个人资料"
    >
      <div data-testid="profile-detail" style={{ padding: '24px' }}>
        {isLoading && <Skeleton active />}

        {!isLoading && isError && (
          <Empty description="加载个人资料失败" data-testid="profile-error" />
        )}

        {!isLoading && !isError && data === undefined && (
          <Empty description="未找到个人资料" data-testid="profile-empty" />
        )}

param(
  [string]$ProjectRoot = 'D:\Agent\banksystem',
  [string]$Container = 'mifos-isolated-postgresql-1'
)

$ErrorActionPreference = 'Stop'
$stamp = (Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ')
$backupRoot = Join-Path $ProjectRoot "backups/core/$stamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$items = @()
foreach ($database in @('fineract_tenants', 'fineract_default')) {
  $inside = "/tmp/$database-$stamp.dump"
  $outside = Join-Path $backupRoot "$database.dump"
  docker exec $Container pg_dump -U postgres -Fc -d $database -f $inside
  if ($LASTEXITCODE -ne 0) { throw "pg_dump failed for $database" }
  docker exec $Container pg_restore -l $inside | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "pg_restore validation failed for $database" }
  docker cp "${Container}:$inside" $outside
  if ($LASTEXITCODE -ne 0) { throw "docker cp failed for $database" }
  docker exec $Container rm -f $inside
  $hash = (Get-FileHash -LiteralPath $outside -Algorithm SHA256).Hash
  $items += [pscustomobject]@{ database = $database; file = $outside; bytes = (Get-Item -LiteralPath $outside).Length; sha256 = $hash; format = 'pg_dump custom (-Fc)' }
}
$manifest = [pscustomobject]@{ createdAtUtc = (Get-Date).ToUniversalTime().ToString('o'); container = $Container; items = $items }
$manifest | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $backupRoot 'manifest.json') -Encoding utf8NoBOM
$manifest | ConvertTo-Json -Depth 4

$unpublishedOutbox=docker exec $name psql -U postgres -d bank_channel -Atc "SELECT count(*) FROM outbox_event WHERE status = 'PENDING';"

  Write-Output "restore=PASS public_tables=$($tables.Trim())"
  Write-Output "invariant_invalid_transfer_status=$($invalidStatus.Trim())"
  Write-Output "invariant_audit_hash_missing=$($auditHashMissing.Trim())"
  Write-Output "invariant_orphan_state_history=$($orphanHistory.Trim())"
  Write-Output "invariant_duplicate_idempotency=$($dupIdempotency.Trim())"
  Write-Output "invariant_unpublished_outbox=$($unpublishedOutbox.Trim())"

  if([int]$invalidStatus.Trim() -gt 0){throw "Invariant failed: invalid transfer status found"}
  if([int]$auditHashMissing.Trim() -gt 0){throw "Invariant failed: audit record hash missing"}
  if([int]$orphanHistory.Trim() -gt 0){throw "Invariant failed: orphan state history records"}
} finally { docker rm -f $name | Out-Null }

package local.bank.channel.identity;

import java.util.List;
import java.util.Map;
import local.bank.channel.FineractAdapter;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;

@RestController
public class CustomerController {
  private final FineractAdapter fineract;
  private final JdbcTemplate jdbc;
  public CustomerController(FineractAdapter fineract, JdbcTemplate jdbc) { this.fineract = fineract; this.jdbc = jdbc; }

  @GetMapping("/api/customer/v1/accounts")
  public Map<String, Object> accounts(@AuthenticationPrincipal Jwt jwt) {
    return Map.of("items", fineract.clientAccounts(linkedClient(jwt.getSubject())).stream().map(this::summary).toList());
  }

  @GetMapping("/api/customer/v1/accounts/{accountId}")
  public Map<String, Object> account(@AuthenticationPrincipal Jwt jwt, @PathVariable String accountId) {
    return fineract.clientAccounts(linkedClient(jwt.getSubject())).stream()
        .filter(a -> accountId.equals(String.valueOf(a.getOrDefault("id", a.get("accountId")))))
        .findFirst().map(this::summary)
        .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Account is not linked"));
  }

private long linkedClient(String subject) {
    List<Long> ids = jdbc.query("SELECT fineract_client_id FROM customer_identity WHERE subject = ?", (rs, n) -> rs.getLong(1), subject);
    if (ids.isEmpty()) throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Customer identity is not linked");
    return ids.get(0);
  }
  public long linkedClientForStatement(String subject) { return linkedClient(subject); }

  private Map<String, Object> summary(Map<String, Object> source) {
    String raw = String.valueOf(source.getOrDefault("accountNo", source.getOrDefault("accountNumber", "")));
    String masked = raw.length() <= 4 ? "****" : "****" + raw.substring(raw.length() - Math.min(4, raw.length()));
    Object balance = source.getOrDefault("accountBalance", source.getOrDefault("balance", "0.00"));
    Object currency = source.getOrDefault("currency", source.getOrDefault("currencyCode", ""));
    if (currency instanceof Map<?, ?> map) { Object code = map.get("code"); currency = code == null ? "" : code; }
    return Map.of("accountId", String.valueOf(source.getOrDefault("id", source.getOrDefault("accountId", ""))), "maskedAccountNumber", masked, "currency", String.valueOf(currency), "balance", String.valueOf(balance));
  }

  @GetMapping("/api/customer/v1/customers/me")
  public Map<String, Object> me(@AuthenticationPrincipal Jwt jwt) {
    String displayName = jwt.getClaimAsString("name");
    if (displayName == null || displayName.isBlank()) displayName = jwt.getClaimAsString("preferred_username");
    if (displayName == null || displayName.isBlank()) displayName = jwt.getSubject();
    return Map.of("customerId", jwt.getSubject(), "displayName", displayName);
  }

  @GetMapping("/api/customer/v1/loans")
  public Map<String,Object> loans(@AuthenticationPrincipal Jwt jwt){return Map.of("items",fineract.clientLoans(linkedClient(jwt.getSubject())));}
}

package local.bank.channel.reconciliation;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;
import local.bank.channel.FineractAdapter;
import org.slf4j.MDC;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ReconciliationService {
  private final JdbcTemplate jdbc;
  private final FineractAdapter fineract;

  public ReconciliationService(JdbcTemplate jdbc, FineractAdapter fineract) {
    this.jdbc = jdbc;
    this.fineract = fineract;
  }

  @Transactional
  public Map<String, Object> run(String type) {
    String correlationId = MDC.get("correlationId");
    if (correlationId == null) correlationId = "no-correlation";

    if (!java.util.Set.of("CHANNEL_TO_CORE", "CHANNEL_TO_CLEARING", "CORE_TO_GENERAL_LEDGER").contains(type))
      throw new IllegalArgumentException("Unsupported reconciliation type");

    int differences;
    String message;

    if (type.equals("CHANNEL_TO_CORE")) {
      differences = jdbc.queryForObject(
          "SELECT count(*) FROM transfer_order WHERE status='SETTLED' AND (core_reference IS NULL OR core_reference='')",
          Integer.class);
      message = differences == 0
          ? "Every settled channel transfer has a Fineract reference"
          : "Settled transfer is missing a Fineract reference";

} else if (type.equals("CHANNEL_TO_CLEARING")) {
      differences = jdbc.queryForObject(
          "SELECT count(*) FROM clearing_payment c LEFT JOIN transfer_order t ON t.transfer_id=c.transfer_id " +
          "WHERE c.status='SETTLED' AND (t.transfer_id IS NULL OR t.status NOT IN ('SETTLED','REVERSED') " +
          "OR t.core_reference IS NULL OR t.core_reference='')",
          Integer.class);
      message = differences == 0
          ? "Clearing settlement statuses and core references are aligned"
          : "Clearing settlement differs from channel transfer status or core posting";

    } else {
      int missingRef = jdbc.queryForObject(
          "SELECT count(*) FROM transfer_order WHERE status IN ('SETTLED','REVERSED') AND (core_reference IS NULL OR core_reference='')",
          Integer.class);
      var entries = fineract.journalEntries();
      BigDecimal debits = BigDecimal.ZERO;
      BigDecimal credits = BigDecimal.ZERO;
      for (var entry : entries) {
        var amount = new BigDecimal(String.valueOf(entry.getOrDefault("amount", "0")));
        Object entryTypeObj = entry.get("entryType");
        String entryType = "";
        if (entryTypeObj instanceof Map<?, ?> etm) entryType = String.valueOf(etm.get("value"));
        else entryType = String.valueOf(entryTypeObj);
        if ("DEBIT".equals(entryType)) debits = debits.add(amount);
        else if ("CREDIT".equals(entryType)) credits = credits.add(amount);
      }
      differences = missingRef;
      if (debits.compareTo(credits) != 0) differences++;
      message = debits.compareTo(credits) == 0
          ? "Core references and journal debit/credit totals are balanced"
          : "Journal debit/credit totals are not balanced: debits=" + debits + " credits=" + credits;
    }

UUID id = UUID.randomUUID();
    String status = differences == 0 ? "MATCHED" : "DIFFERENCE";
    String detailsJson = "{\"correlationId\":\"" + correlationId + "\",\"message\":\"" + message.replace("\"", "\\\"") + "\",\"differenceCount\":" + differences + "}";
    jdbc.update("INSERT INTO reconciliation_run(run_id,reconciliation_type,status,difference_count,details) VALUES(?,?,?,?,?::jsonb)",
        id, type, status, differences, detailsJson);

    Map<String, Object> result = new LinkedHashMap<>();
    result.put("runId", id.toString());
    result.put("type", type);
    result.put("status", status);
    result.put("differenceCount", differences);
    result.put("details", detailsJson);
    result.put("correlationId", correlationId);
    return result;
  }

  public Map<String, Object> latest() {
    var rows = jdbc.query(
        "SELECT run_id,reconciliation_type,status,difference_count,details FROM reconciliation_run ORDER BY created_at DESC LIMIT 1",
        (rs, n) -> {
          var m = new LinkedHashMap<String, Object>();
          m.put("runId", rs.getString(1));
          m.put("type", rs.getString(2));
          m.put("status", rs.getString(3));
          m.put("differenceCount", rs.getInt(4));
          m.put("details", rs.getString(5));
          return m;
        });
    return rows.isEmpty() ? Map.of("status", "NOT_STARTED") : rows.get(0);
  }
}
